(() => {
  const path = window.location.pathname.replace(/\/+$/, '') + '/';
  const enCal = path.endsWith('/en/insolvency-classification-parallel-lives/');
  const esCal = path.endsWith('/es/calificacion-concurso-36-2012-vidas-paralelas/');
  const enAp = path.endsWith('/en/insolvency-36-2012-ap-section-4/');
  const esAp = path.endsWith('/es/concurso-36-2012-ap-seccion-4/');
  if (!enCal && !esCal && !enAp && !esAp) return;
  if (document.querySelector('[data-calificacion-opening-20260816]')) return;

  const es = esCal || esAp;
  const style = document.createElement('style');
  style.textContent = `
    .cal-open{padding:2rem 0}.cal-open-wrap{max-width:1080px;margin:0 auto}.cal-charge{background:#101f26;color:#fff;border-radius:20px;padding:1.5rem;border:1px solid rgba(255,255,255,.12)}
    .cal-kicker{font-size:.76rem;letter-spacing:.09em;text-transform:uppercase;font-weight:800;opacity:.76}.cal-charge h2{font-size:clamp(1.75rem,4vw,2.7rem);line-height:1.08;margin:.45rem 0 .8rem}.cal-charge a{color:#fff;text-decoration:underline}
    .cal-actors{display:grid;grid-template-columns:1.25fr 1fr 1fr;gap:1rem;margin-top:1rem}.cal-actor{background:#fff;color:#13252d;border-radius:16px;padding:1.1rem;border-top:5px solid #8c6b2f}.cal-actor.judge{border-top-color:#7e2929}.cal-role{font-size:.73rem;letter-spacing:.075em;text-transform:uppercase;font-weight:800;color:#6b5841}.cal-actor h3{margin:.35rem 0 .65rem}.cal-actor p{margin:.5rem 0}
    .cal-status,.cal-damage,.cal-media{margin-top:1rem;border-radius:16px;padding:1.1rem 1.2rem}.cal-status{background:#f3efe4;border:1px solid #cabb9d}.cal-damage{background:#fff;border:1px solid rgba(19,37,45,.18)}.cal-media{background:#fbf7ed;border-left:5px solid #8c6b2f}.cal-status h3,.cal-damage h3,.cal-media h3{margin:.3rem 0 .6rem}.cal-damage-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.8rem;margin-top:.8rem}.cal-damage-grid article{background:#f7f7f5;border-radius:13px;padding:.9rem}.cal-damage-grid h4{margin:0 0 .4rem}.cal-note{font-size:.89rem;opacity:.8;margin-top:.9rem}
    @media(max-width:900px){.cal-actors,.cal-damage-grid{grid-template-columns:1fr}.cal-charge{border-radius:0}.cal-open{padding-top:1rem}}
  `;
  document.head.appendChild(style);

  const section = document.createElement('section');
  section.className = 'section cal-open';
  section.dataset.calificacionOpening20260816 = '1';

  const enStatus = `<div class="cal-status"><div class="cal-kicker">CURRENT APPEAL STATUS</div><h3>Audiencia Provincial de Las Palmas · Fourth Section · RPL 2523/2025</h3><p><strong>Latest verified status: awaiting appellate decision/notification.</strong> The classification file was located in the Audiencia Provincial and the later formal correspondence expressly identifies Appeal Roll 2523/2025, Fourth Section. On 13 May 2026, Javier Sixto reported that deliberation and judgment had been fixed for <strong>4 June 2026</strong>. A controlled Gmail search through 16 August 2026 located no appellate judgment or terminating resolution in RPL 2523/2025.</p></div>`;
  const esStatus = `<div class="cal-status"><div class="cal-kicker">ESTADO ACTUAL DEL RECURSO</div><h3>Audiencia Provincial de Las Palmas · Sección Cuarta · RPL 2523/2025</h3><p><strong>Último estado verificado: pendiente de decisión/notificación.</strong> El expediente de calificación fue localizado en la Audiencia Provincial y la correspondencia formal posterior identifica expresamente el Recurso de Apelación 2523/2025, Sección Cuarta. El 13 de mayo de 2026, Javier Sixto comunicó que se había fijado deliberación y fallo para el <strong>4 de junio de 2026</strong>. En la búsqueda controlada de Gmail hasta el 16 de agosto de 2026 no se ha localizado sentencia de apelación ni resolución terminal del RPL 2523/2025.</p></div>`;

  if (enAp || esAp) {
    section.innerHTML = `<div class="shell cal-open-wrap">${es ? esStatus : enStatus}</div>`;
  } else if (esCal) {
    section.innerHTML = `<div class="shell cal-open-wrap">
      <div class="cal-charge">
        <div class="cal-kicker">MI ACUSACIÓN · RESPONSABILIDAD INDIVIDUAL · DOCUMENTOS ABIERTOS AL CONTRASTE</div>
        <h2>No denuncio un simple error: acuso de falsedad consciente en afirmaciones materiales sobre mi conducta.</h2>
        <p>La Sentencia 163/2023 sigue recurrida, pero sus efectos ya han salido del procedimiento. Mi acusación pública es directa: <strong>el AC, el Fiscal y el Juez formularon, respaldaron o adoptaron afirmaciones materialmente falsas sobre lo que hice y dejé de hacer</strong>. Cuando el hecho contrario estaba dentro de la propia esfera de actuación del autor o consta documentalmente que lo conocía, sostengo que la falsedad fue consciente.</p>
        <div class="cal-actors">
          <article class="cal-actor judge"><div class="cal-role">Juez · Alberto López Villarrubia</div><h3>Falsedad consciente en la sentencia · alegación de prevaricación judicial</h3><p><strong>Acuso al juez Alberto López Villarrubia de firmar a sabiendas la Sentencia 163/2023 con afirmaciones fácticas y causales materialmente falsas sobre mi conducta.</strong> No presento los extremos impugnados como un mero error inocente. <strong>Alego que esa conducta constituye prevaricación judicial</strong> en el sentido del artículo 446 del Código Penal, que sanciona al juez o magistrado que, a sabiendas, dicte sentencia o resolución injusta.</p><p>La propia sentencia rechaza partes sustanciales del relato AC/Fiscal y, sin embargo, mantiene conclusiones adversas que denuncio como incompatibles con el expediente y con su propio razonamiento: presunciones sobre la rentabilidad de Pink, tratamiento contradictorio de la cobrabilidad de créditos CEXP y una construcción de no colaboración que no equivale a ausencia de contabilidad ni de actuaciones de rescate.</p><p><strong>Quiero que el expediente certificado y la vista de 25 de julio de 2023 se coloquen al lado de cada afirmación que firmó.</strong> Defenderé documentalmente esta acusación en cualquier procedimiento que se promueva como respuesta.</p></article>
          <article class="cal-actor"><div class="cal-role">Administrador Concursal · Francisco de Borja Rodríguez-Batllori</div><h3>Relato de culpabilidad materialmente falso</h3><p>Le acuso de construir y mantener un relato de obstrucción, falta de colaboración y causalidad mientras existían actuaciones contrarias: entrega de documentación, esfuerzos de continuidad y preservación, impugnaciones para proteger valor y, ya en enero de 2019, una vía financiada para intentar concluir el concurso bajo el antiguo artículo 176 LC.</p><p>La Sentencia 163/2023 rechazó o estrechó partes importantes de ese relato. Cuando el hecho contrario nació dentro de la administración que él mismo ejercía o le fue documentalmente comunicado, <strong>alego que la presentación contraria fue conscientemente falsa</strong>.</p></article>
          <article class="cal-actor"><div class="cal-role">Ministerio Fiscal · Ricardo de Mosteyrín Sampalo</div><h3>Autoridad de Fiscalía prestada a un relato materialmente defectuoso</h3><p>Le acuso de respaldar en un dictamen de dos páginas un paquete de acusaciones materialmente falso e insuficientemente individualizado mientras solicitaba consecuencias personales y patrimoniales extremas. El propio texto contiene la contradicción facial de atribuir la agravación a dolo o culpa del <em>administrador concursal</em> para después identificar a los administradores sociales.</p><p>Menos de dos meses después, la posición adversa del propio Ministerio Fiscal fue invocada al archivar DI 248/2018, donde nosotros pedíamos investigar al AC/CAM. <strong>Alego que ello produjo un refuerzo circular de un marco adverso heredado en vez de un examen independiente de los papeles invertidos.</strong></p></article>
        </div>
        <p class="cal-note">Referencia legal: Código Penal, art. 446, texto consolidado BOE. <a href="https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444" rel="external noopener">Abrir texto oficial →</a></p>
      </div>
      ${esStatus}
      <div class="cal-damage"><div class="cal-kicker">EL RECURSO SIGUE PENDIENTE · EL DAÑO NO</div><h3>Las consecuencias ya se han materializado</h3><div class="cal-damage-grid"><article><h4>Carga procesal y de defensa</h4><p>Recurso, representación, seguimiento, reconstrucción probatoria y actuaciones institucionales siguen siendo necesarias para combatir la sentencia de primera instancia.</p></article><article><h4>Estigma reputacional e institucional</h4><p>La resolución adversa existe, circula y puede ser utilizada como documento de autoridad antes de que la Audiencia Provincial determine si los extremos impugnados se mantienen.</p></article><article><h4>Uso fuera del concurso</h4><p>En enero de 2025 la sentencia entró en una investigación periodística sobre asuntos mucho más amplios que la calificación de LPB y fue vinculada por el periodista a la decisión de no publicar.</p></article></div></div>
      <div class="cal-media"><div class="cal-kicker">ENERO 2025 · ELECONOMISTA</div><h3>Mi acusación: LPAM instrumentalizó la sentencia recurrida para bloquear el artículo</h3><p>Alego que <strong>Laura Patricia Acosta Matos</strong> instrumentalizó la Sentencia 163/2023, ya recurrida, a través del canal de respuesta CAM/Acosta Matos para impedir que la investigación de elEconomista se publicara. La secuencia documentada muestra la petición de esperar hasta el lunes mientras se aportaba material judicial, la recepción el lunes del archivo llamado <em>AUTO CONCURSO CULPOSO.pdf</em> y la comunicación de Javier Romera de que “con esto” no podían publicar.</p><p>El documento no era un Auto que resolviera “Sun Park”: era la Sentencia 163/2023 sobre la calificación de LPB y no resolvía muchas de las cuestiones centrales que elEconomista investigaba — Meeting Point/FTI, propiedad y autoridad, RIC/RICPE, inversión e incentivos o financiación pública. La cuenta que transmitió físicamente el archivo sigue siendo una cuestión de procedencia distinta de la función documentada del canal de respuesta.</p><a class="button secondary" href="../eleconomista-javier-romera-enero2025/">Abrir el expediente separado de elEconomista →</a></div>
    </div>`;
  } else {
    section.innerHTML = `<div class="shell cal-open-wrap">
      <div class="cal-charge">
        <div class="cal-kicker">MY ACCUSATION · INDIVIDUAL ACCOUNTABILITY · DOCUMENTS OPEN TO TEST</div>
        <h2>I am not alleging a mere mistake: I accuse them of knowing falsehood on material facts about my conduct.</h2>
        <p>Judgment 163/2023 remains under appeal, but its effects have already travelled beyond the proceeding. My public accusation is direct: <strong>the AC, Fiscal and Judge advanced, endorsed or adopted materially false statements about what I did and did not do</strong>. Where the contrary fact sat within the author's own sphere of responsibility or the record demonstrates that the author knew it, I say the falsehood was knowing.</p>
        <div class="cal-actors">
          <article class="cal-actor judge"><div class="cal-role">Judge · Alberto López Villarrubia</div><h3>Knowing falsehood in the judgment · allegation of judicial prevarication</h3><p><strong>I accuse Judge Alberto López Villarrubia of knowingly signing Judgment 163/2023 with materially false factual and causal findings about my conduct.</strong> I do not present the challenged findings as mere innocent error. <strong>I allege that this conduct amounts to judicial prevarication</strong> within Article 446 of the Spanish Criminal Code, which addresses a judge or magistrate who knowingly issues an unjust judgment or resolution.</p><p>The judgment itself rejects substantial parts of the AC/Fiscal narrative yet retains adverse conclusions that I say are incompatible with the record and with its own reasoning: presumptions about Pink's profitability, contradictory treatment of the recoverability of CEXP credits, and a non-collaboration construction that is not the same thing as absence of accounting or absence of rescue activity.</p><p><strong>I want the complete certified docket and the 25 July 2023 hearing record placed beside every factual proposition he signed.</strong> I will defend this accusation with the documentary record in any proceeding brought in response.</p></article>
          <article class="cal-actor"><div class="cal-role">Insolvency Administrator · Francisco de Borja Rodríguez-Batllori</div><h3>A materially false culpability narrative</h3><p>I accuse the AC of constructing and maintaining a narrative of obstruction, non-collaboration and causation while contrary conduct existed: document production, attempts to preserve operation and value, challenges intended to protect value and, by January 2019, a contemporaneously recorded financed route to seek conclusion of the insolvency under former Article 176 LC.</p><p>Judgment 163/2023 rejected or narrowed important parts of that narrative. Where the contrary fact arose within the administration he himself conducted or was demonstrably communicated to him, <strong>I allege the contrary portrayal was knowingly false</strong>.</p></article>
          <article class="cal-actor"><div class="cal-role">Public Prosecutor · Ricardo de Mosteyrín Sampalo</div><h3>Prosecutorial authority placed behind a materially defective narrative</h3><p>I accuse the Fiscal of endorsing in a two-page opinion a materially false and insufficiently individualised accusation package while seeking extreme personal and patrimonial consequences. The text itself contains the facial contradiction of attributing aggravation to intent or fault of the <em>insolvency administrator</em> and then identifying the social administrators as responsible.</p><p>Less than two months later, the Ministerio Fiscal's own adverse classification position was invoked when DI 248/2018 — our complaint against the AC/CAM perimeter — was archived. <strong>I allege that this produced circular reinforcement of an inherited adverse frame rather than independent scrutiny of reversed procedural roles.</strong></p></article>
        </div>
        <p class="cal-note">Legal reference: Spanish Criminal Code, Article 446, consolidated BOE text. <a href="https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444" rel="external noopener">Open official text →</a></p>
      </div>
      ${enStatus}
      <div class="cal-damage"><div class="cal-kicker">THE APPEAL IS PENDING · THE DAMAGE IS NOT</div><h3>Consequences have already materialised</h3><div class="cal-damage-grid"><article><h4>Procedural and defence burden</h4><p>Appeal, representation, monitoring, evidential reconstruction and institutional work remain necessary to challenge the first-instance judgment.</p></article><article><h4>Reputational and institutional stigma</h4><p>The adverse judgment exists, circulates and can be used as an authority document before the Audiencia Provincial determines whether the challenged findings stand.</p></article><article><h4>Use outside the insolvency</h4><p>By January 2025 the judgment had entered a newsroom investigation concerning matters materially wider than LPB's classification and was linked by the journalist to the decision not to publish.</p></article></div></div>
      <div class="cal-media"><div class="cal-kicker">JANUARY 2025 · ELECONOMISTA</div><h3>My accusation: LPAM instrumentalised the appealed judgment to block the article</h3><p>I allege that <strong>Laura Patricia Acosta Matos</strong> instrumentalised Judgment 163/2023, already under appeal, through the CAM/Acosta Matos response channel to stop the elEconomista investigation from being published. The documented sequence shows the request to wait until Monday while judicial material was supplied, Monday receipt of the file labelled <em>AUTO CONCURSO CULPOSO.pdf</em>, and Javier Romera's communication that “con esto” the outlet could not publish.</p><p>The document was not an Auto determining “Sun Park”: it was Judgment 163/2023 in LPB's classification and did not decide many central matters elEconomista was investigating — Meeting Point/FTI, ownership and authority, RIC/RICPE, investment and public incentives or funding. The account that physically transmitted the file remains a separate provenance question from the documented function of the response channel.</p><a class="button secondary" href="../eleconomista-javier-romera-january2025/">Open the separate elEconomista evidence page →</a></div>
    </div>`;
  }

  const hero = document.querySelector('.hero.cal-hero') || document.querySelector('main .hero') || document.querySelector('main');
  if (hero && hero.parentNode) hero.insertAdjacentElement('afterend', section);

  if (enCal || esCal) {
    const strip = document.querySelector('.status-strip');
    if (strip && strip.children[1]) {
      strip.children[1].innerHTML = es
        ? '<strong>Estado procesal</strong>Audiencia Provincial de Las Palmas · Sección Cuarta · RPL 2523/2025 · pendiente de decisión/notificación.'
        : '<strong>Procedural status</strong>Audiencia Provincial de Las Palmas · Fourth Section · RPL 2523/2025 · awaiting decision/notification.';
    }
  }
})();